<?php $title='Mi panel'; ?><div class="level"><div><h1 class="title">Mi panel</h1><p class="subtitle is-6">Tus boletos, rifas y notificaciones.</p></div></div><div class="columns"><div class="column"><div class="stat-card"><small>Boletos</small><strong><?= count($tickets) ?></strong></div></div><div class="column"><div class="stat-card"><small>Notificaciones</small><strong><?= count($notifications) ?></strong></div></div><div class="column"><div class="stat-card"><small>Rifas activas</small><strong><?= count($raffles) ?></strong></div></div></div><div class="columns"><div class="column is-7"><div class="box"><h2 class="title is-5">Mis boletos</h2><div class="table-container"><table class="table is-fullwidth is-hoverable"><thead><tr><th>Rifa</th><th>Producto</th><th>Folio</th><th>Estado</th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td><?= e($t['code']) ?></td><td><?= e($t['product_name']) ?></td><td>#<?= e($t['folio']) ?><?= $t['is_winner']?' 🏆':'' ?></td><td><?= e($t['raffle_status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="column is-5"><div class="box"><h2 class="title is-5">Últimas notificaciones</h2><?php foreach(array_slice($notifications,0,5) as $n): ?><article class="media notif"><div class="media-content"><strong><?= e($n['title']) ?></strong><p><?= e($n['message']) ?></p><small><?= e($n['channel']) ?> · <?= e($n['status']) ?></small></div></article><?php endforeach; ?></div></div></div>
